"use client"

import { createFastLink, type FastLinkIntent } from "@fast-link/core"
import { mergeProps, renderElement, type PartProps } from "@ui-sdk/react/primitive"
import { useCallback, useEffect, useRef, type RefCallback } from "react"

type FastLinkOptions = {
  /** `false` leaves every press native. */
  enabled?: boolean
  /** Navigates instead of `location.assign`, for a client-side router. Receives the authored `href`. */
  onFollow?: (href: string, details: { url: URL; anchor: HTMLAnchorElement; event: PointerEvent }) => void
}

const optOut = "[data-no-fast-link]"

// Core reads `data-no-fast-link` only between the pressed element and its anchor. Checking the press here, in a
// capture listener added before core's on the same root, lets an ancestor (a region, `<body>`) opt out too.
function attachFastLink(root: HTMLElement, options: () => FastLinkOptions) {
  let press: PointerEvent | undefined
  const navigate = (intent: FastLinkIntent) => {
    const { onFollow } = options()
    if (onFollow && press) onFollow(intent.href, { url: intent.url, anchor: intent.anchor, event: press })
    else intent.anchor.ownerDocument.defaultView?.location.assign(intent.url.href)
  }
  const onPointerDown = (event: PointerEvent) => {
    press = event
    const target = event.target instanceof Element ? event.target : null
    controller.update({ enabled: options().enabled !== false && !target?.closest(optOut), navigate })
  }
  root.addEventListener("pointerdown", onPointerDown, { capture: true })
  const controller = createFastLink(root, { enabled: options().enabled !== false, navigate })
  return () => {
    root.removeEventListener("pointerdown", onPointerDown, { capture: true })
    controller.destroy()
  }
}

/**
 * A ref that follows same-origin links on a primary mouse press instead of on release, on the element itself (an
 * anchor) or on the anchors inside it. Keyboard, touch, pen and modified or non-primary presses stay native.
 */
function useFastLink<T extends HTMLElement>(options: FastLinkOptions = {}): RefCallback<T> {
  const latest = useRef(options)
  useEffect(() => {
    latest.current = options
  })
  return useCallback((element: T | null) => (element ? attachFastLink(element, () => latest.current) : undefined), [])
}

type FastLinkRegionProps = PartProps<"div"> & FastLinkOptions

/** Fast links for plain anchors in prose or rendered HTML; `Link` already has them. */
function FastLinkRegion({ enabled, onFollow, render, ...props }: FastLinkRegionProps) {
  const ref = useFastLink<HTMLDivElement>({ enabled, onFollow })
  return renderElement("div", mergeProps({ "data-slot": "fast-link-region", ref }, props), render)
}

export { FastLinkRegion, useFastLink }
export type { FastLinkOptions, FastLinkRegionProps }

import { definePrimitive, dispatch, type ChangeDetails } from "@ui-sdk/core"

type LinkFollowDetails = ChangeDetails<"follow">

type LinkOptions = {
  href?: string
  onFollow?: (href: string, details: LinkFollowDetails) => void
}

function isPlainClick(event: MouseEvent) {
  return event.button === 0 && !event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey
}

// UI SDK ships no link part, so a link is invisible to agents unless the app takes over following it. With
// `onFollow` the app decides what following means (a router push, a confirmation), for people and agents alike.
const link = definePrimitive({
  name: "link",
  options: { href: "string", onFollow: "callback" },
  state: (options: LinkOptions) => ({ value: options.href ?? "" }),
  sync: (options) => ({ value: options.href ?? "" }),
  api: (context) => ({
    follow(event?: Event) {
      const { href = "" } = context.options()
      return !dispatch(context, "onFollow", href, { reason: "follow", event })
    },
  }),
  slots: (slot) => ({
    root: slot({
      on: {
        click: (event, { api }) => {
          const mouse = event as MouseEvent
          if (mouse.defaultPrevented || !isPlainClick(mouse)) return
          mouse.preventDefault()
          api.follow(mouse)
        },
      },
    }),
  }),
  agent: { actions: ["follow"] },
})

export { isPlainClick, link }
export type { LinkFollowDetails, LinkOptions }

"use client"

import { mergeProps, renderElement, usePart, usePrimitive, type PartProps } from "@ui-sdk/react/primitive"
import { cva } from "class-variance-authority"
import type { AriaAttributes, ReactNode } from "react"

import { useFastLink } from "@/components/ui/fast-link"
import { link, type LinkOptions } from "@/components/ui/link-primitive"
import { cn } from "@/lib/utils"

type LinkVariant = "inline" | "nav" | "muted" | "standalone" | "plain"

const focusRing =
  "rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"

// `plain` adds nothing, not even the focus ring, so a row or card styled through className keeps its own.
const linkVariants = cva("", {
  variants: {
    variant: {
      inline: "text-link underline decoration-1 underline-offset-2 hover:decoration-2",
      nav: "text-muted-foreground underline-offset-4 transition-colors duration-micro ease-standard hover:text-foreground hover:underline aria-[current]:font-medium aria-[current]:text-foreground",
      muted:
        "text-muted-foreground underline-offset-2 transition-colors duration-micro ease-standard hover:text-foreground hover:underline",
      standalone:
        "touch-target inline-flex items-center gap-inline font-medium text-link underline-offset-4 hover:underline [&_svg]:size-4 [&_svg]:shrink-0",
      plain: "",
    },
  },
  compoundVariants: [{ variant: ["inline", "nav", "muted", "standalone"], class: focusRing }],
  defaultVariants: { variant: "inline" },
})

type LinkProps = Omit<PartProps<"a">, "children"> & {
  children?: ReactNode
  /**
   * `inline` sits in running text (underlined at rest), `nav` and `muted` list links (underlined on hover),
   * `standalone` is a call to action on its own line, `plain` leaves the look to `className` (a card, a row).
   */
  variant?: LinkVariant
  /** Another site: a trailing icon and `rel="noopener noreferrer"`. Opens in the same tab unless `newTab`. */
  external?: boolean
  /** Opens in a new tab (`target="_blank"`) and says so to screen readers with `newTabLabel`. */
  newTab?: boolean
  newTabLabel?: string
  /** Marks the link to the current page (`aria-current="page"`), or pass another `aria-current` token. */
  current?: boolean | Exclude<AriaAttributes["aria-current"], boolean | "true" | "false">
  /**
   * Takes over a plain click (modified clicks keep the browser's behaviour), for client-side routing. It also
   * offers agents a `follow` action that calls it; links without it are invisible to agents.
   */
  onFollow?: LinkOptions["onFollow"]
  /**
   * Follows a same-origin link on a primary mouse press instead of on release (default `true`); keyboard, touch, pen
   * and modified presses stay native. Off for `external` links, and for a `render`ed router link without `onFollow`,
   * which navigates on its own click. `data-no-fast-link` on any ancestor turns it off for a region.
   */
  fast?: boolean
}

function ExternalIcon() {
  return (
    <svg
      data-slot="link-external-icon"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className="ms-px inline-block size-3 shrink-0 align-baseline rtl:-scale-x-100"
    >
      <path d="M7 17 17 7M8 7h9v9" />
    </svg>
  )
}

function linkProps({
  variant = "inline",
  external = false,
  newTab = false,
  newTabLabel = "(opens in a new tab)",
  current,
  className,
  children,
  rel,
  target,
  ...props
}: Omit<LinkProps, "onFollow" | "render" | "fast">) {
  return {
    "data-slot": "link",
    "data-variant": variant,
    "data-external": external ? "" : undefined,
    "aria-current": current === true ? ("page" as const) : current || undefined,
    rel: external ? ["noopener noreferrer", rel].filter(Boolean).join(" ") : rel,
    target: newTab ? "_blank" : target,
    className: cn(linkVariants({ variant }), className),
    children: (
      <>
        {children}
        {external && <ExternalIcon />}
        {newTab && <span className="sr-only"> {newTabLabel}</span>}
      </>
    ),
    ...props,
  }
}

function FollowLink({ onFollow, render, fast = true, ...props }: LinkProps) {
  const handle = usePrimitive(link, { href: props.href, onFollow })
  const ref = useFastLink<HTMLAnchorElement>({
    enabled: fast && !props.external,
    onFollow: (_href, { event }) => handle.api.follow(event),
  })
  return usePart(handle, "root", {}, { ...mergeProps(linkProps(props), { ref }), render }, "a")
}

// Without `onFollow`, a router element navigates on its own click, so a press must not navigate first.
function PlainLink({ render, fast = true, ...props }: Omit<LinkProps, "onFollow">) {
  const ref = useFastLink<HTMLAnchorElement>({ enabled: fast && !props.external && !render })
  return renderElement("a", mergeProps(linkProps(props), { ref }), render)
}

function Link({ onFollow, ...props }: LinkProps) {
  if (onFollow) return <FollowLink onFollow={onFollow} {...props} />
  return <PlainLink {...props} />
}

export { Link, linkVariants }
export type { LinkProps, LinkVariant }
